import{_ as t,o,c as a,a2 as s}from"./chunks/framework.k9nOhppk.js";const g=JSON.parse('{"title":"The future of Eyelang","description":"","frontmatter":{"title":"The future of Eyelang"},"headers":[],"relativePath":"future-of-eyelang.md","filePath":"future-of-eyelang.md","lastUpdated":1791864160000}'),n={name:"future-of-eyelang.md"};function r(i,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="the-future-of-eyelang" tabindex="-1">The future of Eyelang <a class="header-anchor" href="#the-future-of-eyelang" aria-label="Permalink to &quot;The future of Eyelang&quot;">​</a></h1><p>This page covers three things: what Eyelang already is, what you can build with it today, and everything planned next, in order. It describes the code on <code>dev</code> on 2026-10-13. When a task lands, this page changes in the same commit. Feature by feature, <a href="/reference/status">What runs today</a> is the finer record. Task by task, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/ROADMAP.md" target="_blank" rel="noreferrer">ROADMAP.md</a> and the <a href="https://github.com/ruxxzebre/eyelang/issues" target="_blank" rel="noreferrer">GitHub issues</a> are.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p><strong>Eyelang lets you write a program that runs for days (waits for people, keeps state, calls services that fail) as plainly as a script, and the compiler catches the mistakes such programs usually ship with.</strong> Five promises say what you get:</p><ol><li><strong>Waiting is one line.</strong> <code>sleep!(3 days)</code>, <code>next!(answered, within: 6 h)</code> and <code>@on(daily(07:40, in: &quot;Europe/Dublin&quot;))</code> replace the queue, the cron table and the <code>next_run_at</code> column.</li><li><strong>Replays can&#39;t go wrong.</strong> Every durable step in a job is marked <code>!</code>. A resumed run gets each step&#39;s recorded result instead of calling again, and code that would see a different value on replay doesn&#39;t compile.</li><li><strong>State has one owner.</strong> An entity&#39;s data changes only through its own methods. Each call tree is one transaction, and you write no locks.</li><li><strong>Outside calls are typed and settle once.</strong> A contract types every call to another service. A keyed command never does its work twice, and a lost reply is <code>Uncertain</code> until <code>.reconcile!()</code> settles it.</li><li><strong>Days of behaviour test in milliseconds.</strong> <code>advance(3 days)</code> moves a fake clock, and fakes replay recorded replies.</li></ol><p><a href="/design/goals">Goals</a> holds the promises in full and the principles every change is weighed against. Everything below is a means to them.</p><h2 id="where-it-stands" tabindex="-1">Where it stands <a class="header-anchor" href="#where-it-stands" aria-label="Permalink to &quot;Where it stands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>What it brings</th><th>State</th></tr></thead><tbody><tr><td><strong>v0.1.0</strong></td><td>Write, check, format, run and test programs with entities, jobs and views, on an in-memory store with a controllable clock</td><td>Released 2026-10-10</td></tr><tr><td><strong>v0.2.0</strong></td><td>Durable runs on a journal or Postgres, typed model calls, <code>dyn Trait</code>, task groups and channels, <code>@memory</code>, <code>@priority</code> and <code>@budget</code> enforced, approvals that reach people</td><td>Released 2026-10-11</td></tr><tr><td><strong>v0.3</strong></td><td>Contracts with other services, network policy and Go/TypeScript code generated from them, model tools, coding agents</td><td>11 of 13 tasks done. Left: 6.6 and 6.8, its exit tests</td></tr><tr><td><strong>v0.4</strong></td><td>Native code through C with reference counting; jobs as state machines; the runner hosting compiled code</td><td>9 of 14 tasks done; 7.9&#39;s work is merged and closes with 7.6. Its exit test, the digest running natively (7.6), is the next piece of work</td></tr><tr><td><strong>v1.0</strong></td><td>Syntax freeze, migration tooling, <code>eye why</code>, hot code replacement, documentation</td><td>Planned</td></tr></tbody></table><p>Nearly every feature <a href="/reference/status">What runs today</a> lists is done; that page names each one still partial or not built. The biggest gaps are coding agents (6.8) and native compilation of entities, jobs and contracts (7.6).</p><h2 id="what-is-implemented" tabindex="-1">What is implemented <a class="header-anchor" href="#what-is-implemented" aria-label="Permalink to &quot;What is implemented&quot;">​</a></h2><h3 id="the-language" tabindex="-1">The language <a class="header-anchor" href="#the-language" aria-label="Permalink to &quot;The language&quot;">​</a></h3><ul><li><p><strong>The core.</strong> Values and types:</p><ul><li><code>Int</code> with arbitrary precision, divisors checked as <code>NonZero</code>;</li><li>fixed-width integers, floats, strings with interpolation, chars, <code>Bytes</code>;</li><li>durations, sizes, dates, times of day, instants and zones checked when compiled.</li></ul><p>Also records, variants and enums (<code>T.variants()</code>, <code>T.parse(s)</code>), lists, sets and maps, tuples, pipes, lambdas, and pattern matching with exhaustiveness checks and <code>let … else</code>. Errors are <code>Result</code> only, with <code>?</code>.</p></li><li><p><strong>Types and traits.</strong> Inference inside bodies, against signatures as written. Generics with <code>where</code> bounds, traits with default methods and coherent impls, and operators as traits. Derived <code>Eq</code>, <code>Ord</code>, <code>Show</code>, <code>Hash</code>, <code>Save</code> and <code>Schema</code>. <code>dyn Trait</code> as a type of its own, and any function callable as a method.</p></li><li><p><strong>Mutation without aliasing.</strong> <code>var</code>, <code>mut</code> parameters marked at the call, element assignment (<code>xs[i] = v</code>), and no variable passed as <code>mut</code> twice in one call. Values, not shared objects.</p></li><li><p><strong>Effects.</strong> Inferred, and stated with <code>uses</code> on public functions. <code>!</code> marks every recorded step in a job. A secret, a handle or a function can&#39;t be held across a <code>!</code> unless it can be saved. A function kept in data is held to its type&#39;s effects.</p></li><li><p><strong>Structured concurrency.</strong> <code>parallelMap</code>, <code>both</code>, <code>race</code>, <code>timeout</code>, task groups with <code>spawn</code>, and bounded channels. On a test&#39;s clock they take turns by wake time, so tests give the same result every run.</p></li></ul><h3 id="durable-programs" tabindex="-1">Durable programs <a class="header-anchor" href="#durable-programs" aria-label="Permalink to &quot;Durable programs&quot;">​</a></h3><ul><li><strong>Entities.</strong> Records with an identity, changed only through their own methods. Each call tree is one transaction. Entities are versioned with <code>@version(N)</code>, with <code>migrate from N</code> chained when a row is loaded.</li><li><strong>Jobs.</strong> Functions that run in the background and wait. A run waits with <code>sleep!</code>, <code>sleepUntil!</code>, <code>next!</code>, <code>poll!</code> and <code>approval!</code>, starts once per key, and is scheduled with <code>daily</code>, <code>weekdays</code> and <code>every</code> in a zone. Runs are limited with <code>@concurrency</code>, <code>@limit</code>, <code>@deadline</code>, <code>@memory</code>, <code>@priority</code> and <code>@budget</code>.</li><li><strong>Resuming.</strong> A job resumes from checkpoints at its statements and replays only the steps since. So a run that never ends, such as a watcher, stops growing. A waiting run costs a 48-byte handle in memory; 20,000 waiting runs take about 7 MB above an idle runner.</li><li><strong>Views, events and schedules.</strong> Views over entities, with <code>enters</code> and <code>leaves</code> triggers; <code>publish</code> and <code>@on(event(…))</code>. Another program&#39;s events arrive as a <code>POST /events/&lt;topic&gt;</code> to the program&#39;s port, under the contract&#39;s <code>@auth</code>.</li><li><strong>Stores.</strong> The in-memory store is written in Eyelang itself. The journal (<code>eye run</code>, the default) and Postgres (<code>--store postgres://…</code>) survive restarts of the runner and of the database. <code>eye runs</code> lists every run, what it waits for and its steps. <code>eye runs --retry ID</code> starts a failed run again, replaying its steps.</li><li><strong>Approvals.</strong> <code>approval!(…, from: person, within: 2 days)</code> reaches people through <code>approvals.requested</code>, and is answered by id, only by the person asked: <code>eye approve</code>, <code>eye decline</code>, or the program&#39;s own buttons.</li></ul><h3 id="other-services-and-models" tabindex="-1">Other services and models <a class="header-anchor" href="#other-services-and-models" aria-label="Permalink to &quot;Other services and models&quot;">​</a></h3><ul><li><strong>Contracts.</strong> Typed operations over HTTP, with <code>@http</code>, <code>@auth</code>, <code>@port</code> and <code>@allow</code> enforced. Commands carry keys (<code>@key(required)</code>), and a lost reply is <code>Uncertain</code> until <code>.reconcile!()</code> settles it. <code>@fresh</code> and <code>@destructive</code> are checked. <code>eye run</code> serves a contract over HTTP on its <code>@port</code>.</li><li><strong>Generated boundaries.</strong> <code>eye gen go</code> and <code>eye gen ts</code> write types, clients and server stubs. <code>eye gen policy</code> writes Kubernetes NetworkPolicy from what each module may call.</li><li><strong>Model calls.</strong> <code>ai.generate!</code> asks a model for a value of an Eyelang type, by its schema, from Anthropic or any OpenAI-compatible gateway, within <code>@budget</code>. Functions passed as <code>tools:</code> are run when the model calls them, each a recorded step; a <code>@destructive</code> tool waits for approval.</li><li><strong>Foreign code.</strong> <code>extern</code> functions from Go hosts (the <code>host</code> package embeds Eyelang in a Go program) and from C libraries (<code>@library</code>, loaded at run time). <code>extern type</code> names a value foreign code owns.</li></ul><h3 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h3><ul><li><code>eye test</code> gives each test a fresh store and a clock that moves only with <code>advance(…)</code>.</li><li><code>fakes(module, from: &quot;recordings/&quot;)</code> replays recorded replies, checked against the contract, and <code>sent.calls(op)</code> shows what a fake received.</li><li><code>eye test --live</code> runs against the real services and models. <code>--record</code> writes what they answered for the next plain run.</li><li>Tests don&#39;t reach the network: a call without fakes, outside <code>--live</code>, fails the test and names what to add.</li><li><code>with memory(…)</code> sets the memory a test&#39;s runs are admitted against.</li></ul><h3 id="native-compilation-v0-4-in-progress" tabindex="-1">Native compilation (v0.4, in progress) <a class="header-anchor" href="#native-compilation-v0-4-in-progress" aria-label="Permalink to &quot;Native compilation (v0.4, in progress)&quot;">​</a></h3><p><code>eye build</code> compiles a program to one native binary through C11, built by a pinned <code>zig cc</code> that <code>eye</code> fetches and checks itself. It cross-compiles to every release target from any host.</p><ul><li><strong>Done.</strong> The typed IR (7.1) and a monomorphic low IR (7.2). The C back end and core runtime (7.4). Reference counting in the low IR, with drops after last use and updates in place when a value is unique (7.5). Values laid out by type: enums as a byte, records up to 64 bytes as C structs, <code>Option</code> in a niche, lists holding their elements inline (most of 7.13). Cheap fixes (7.14). Every compiled program&#39;s tests are checked line by line against the interpreter at both <code>-O0</code> and <code>-O2</code> (7.8).</li><li><strong>The core gaps (7.9)</strong> are closed: time methods, <code>random</code>, <code>fs.lines</code>, <code>toJson</code>, saved values encoded and decoded byte for byte as the interpreter does them, and <code>http.get</code> and <code>regex</code> as host calls the Go runner answers.</li><li><strong>Speed.</strong> Against the same programs in Go, native code takes <strong>0.85× Go&#39;s time and 0.36× its memory</strong> on the geometric mean of nine benchmarks. It beats Go on trees, records, strings, logs and Eyelang&#39;s own lexer (<a href="/internals/benchmarks">Benchmarks against Go</a>).</li><li><strong>Hosting (7.6), the runner&#39;s side.</strong> <code>eye build --runner</code> links a program&#39;s C into the Go runner through cgo, using a pinned Go toolchain. The result is one static binary on Linux, cross-built for macOS. Through <code>interp.Native</code> and <code>cgen/hosted/eye_host.h</code>, the runner runs a compiled program&#39;s <code>main</code>, tests, entity methods and jobs on the journal and on Postgres. It answers the program&#39;s callbacks, records its steps and resumes it after a restart.</li></ul><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><ul><li><code>eye fmt</code> and <code>eye fix</code>, which rewrites code the language changed under.</li><li><code>eye check</code>, with an error class for every error the spec promises, each at its exact place.</li><li><code>eye doc</code>, which writes the API reference from <code>##</code> comments.</li><li><code>eye repl</code>, whose jobs run on a clock that <code>:advance</code> moves.</li><li><code>eye lsp</code>: errors at their spans, hover, completion, go to definition, references, formatting. The VS Code extension is its client.</li><li>The tree-sitter grammar, for Neovim, Helix and Zed, kept in step with the compiler&#39;s parser by a conformance suite and a fuzzer.</li><li><a href="/playground">The playground</a>: the checker, interpreter, formatter and language server built for WebAssembly, in the browser. Two programs can call each other through a contract in the page.</li><li><a href="/reference/cli">The command reference</a> has every command and flag.</li></ul><h3 id="programs-written-in-it" tabindex="-1">Programs written in it <a class="header-anchor" href="#programs-written-in-it" aria-label="Permalink to &quot;Programs written in it&quot;">​</a></h3><ul><li><strong>The homelab&#39;s workloads</strong> (<code>testdata/lab</code>): the morning digest, Notify, train reminders and NetBird access approvals. These are the programs that decide what the language needs.</li><li><strong>The morning digest</strong> runs in the homelab on Postgres, in shadow mode beside the TypeScript digest it is to replace.</li><li><strong>Eyelang&#39;s own lexer, in Eyelang</strong> (S.1). It gives the same 24,959 tokens as the Go lexer on the conformance suite, and compiles natively.</li></ul><h2 id="what-you-can-build-with-it-today" tabindex="-1">What you can build with it today <a class="header-anchor" href="#what-you-can-build-with-it-today" aria-label="Permalink to &quot;What you can build with it today&quot;">​</a></h2><p>Any program that waits, keeps state and calls services that fail, where you would otherwise wire together a web framework, a database table, a queue, a cron, a retry library and hand-made idempotency keys:</p><ul><li>reminders and follow-ups (&quot;three days after the invoice, unless it&#39;s paid&quot;);</li><li>approval flows that wait days for a person, with buttons;</li><li>scheduled digests and reports that call models for typed summaries;</li><li>monitors and watchers that run forever without growing;</li><li>webhook delivery and other commands that must settle exactly once;</li><li>AI agents whose model calls and tool calls are recorded steps, resumed after a crash without calling a tool twice.</li></ul><p><a href="/examples/">Examples</a> has runnable programs of each kind, and <a href="/tutorial/">the tutorial</a> builds one from the start. Today such programs run on the interpreter under <code>eye run</code>, on the journal or on Postgres. Programs of the core language alone (no entities or jobs) also compile to fast native binaries with <code>eye build</code>.</p><h2 id="what-is-planned" tabindex="-1">What is planned <a class="header-anchor" href="#what-is-planned" aria-label="Permalink to &quot;What is planned&quot;">​</a></h2><p>Every open item, issue by issue, with the undecided open questions and the decisions waiting on the owner, is listed in <a href="/whats-left">What&#39;s left</a>.</p><h3 id="v0-4-native-compilation-now" tabindex="-1">v0.4: native compilation (now) <a class="header-anchor" href="#v0-4-native-compilation-now" aria-label="Permalink to &quot;v0.4: native compilation (now)&quot;">​</a></h3><p>The work in order. The owner&#39;s native-focus checkpoint is close to reached: <code>NaN</code> equal to itself, <code>with memory(…)</code> in tests, events between programs, <code>eye runs --retry</code>, and the core gaps in C (7.9) are done.</p><ol><li><p><strong>7.6, the runner hosts compiled programs (#79), v0.4&#39;s exit test.</strong> The runner&#39;s side is done. Two things remain:</p><ul><li>the C back end writing the hosting entry points: the program&#39;s tables, entity methods, jobs as state machines over saved frames, and encoders at the boundary;</li><li><code>eye build --runner</code> building real programs with the runner&#39;s module inside.</li></ul><p><strong>Done when</strong> the morning digest runs as a native job on the journal and on Postgres, with its idle memory and resume time recorded beside the interpreter&#39;s. Then v0.4 is released.</p></li><li><p><strong>Before the checkpoint closes:</strong></p><ul><li>the rest of 7.13 (#117): maps specialised per key type, and strings and <code>Bytes</code> as views, so slicing them stops copying.</li></ul></li><li><p><strong>7.11, faster than Go (#114).</strong> Native code beats Go on time on every benchmark, and on memory for every program without entities or jobs. Tracked by <code>go run ./tools/bench --check</code>.</p></li><li><p><strong>7.12, reuse and fault regions (#115).</strong> A <code>match</code> arm reuses the cell it matched, and a failing test frees what it allocated.</p></li></ol><h3 id="v0-3-what-is-left" tabindex="-1">v0.3: what is left <a class="header-anchor" href="#v0-3-what-is-left" aria-label="Permalink to &quot;v0.3: what is left&quot;">​</a></h3><ul><li><strong>6.6, Notify&#39;s boundary from its contract (#58).</strong> The homelab&#39;s Notify builds against generated TypeScript types, so a breaking change to the contract fails its build. This needs the homelab repository.</li><li><strong>6.8, the <code>agents</code> module (#60).</strong> <code>claude.start!</code> and <code>codex.start!</code> begin a coding-agent session that a job owns. The job waits without memory and picks the session up after a restart. Tools are served over MCP, and permission requests are answered through <code>approval!</code>.</li></ul><h3 id="open-issues-outside-the-phases" tabindex="-1">Open issues outside the phases <a class="header-anchor" href="#open-issues-outside-the-phases" aria-label="Permalink to &quot;Open issues outside the phases&quot;">​</a></h3><ul><li><strong>Library gaps:</strong><ul><li>a secure random token, and JSON decoded into typed values (#153);</li><li>HTTP beyond <code>get</code>, and contracts with more than one base URL, for webhooks (#144).</li></ul></li><li><strong>Docs and the playground:</strong><ul><li>the whole reference as one <code>llms-full.txt</code> for agents (#152);</li><li>homelab-specific teaching examples replaced (#148);</li><li>the playground&#39;s 24-hour run limit and its files (#147).</li></ul></li><li><strong>The repository:</strong> <code>main</code> still holds Eyelang 1; <code>dev</code> should become the default (#149).</li></ul><h3 id="after-v0-4" tabindex="-1">After v0.4 <a class="header-anchor" href="#after-v0-4" aria-label="Permalink to &quot;After v0.4&quot;">​</a></h3><ul><li><strong>S.2, the runner in Eyelang (#116).</strong> The durable runner moves from Go into Eyelang part by part, so a native job program has no Go in it and can beat Go on memory too. <strong>Done when</strong> the digest runs natively with no Go in its binary, using less memory than under the Go runner.</li><li><strong>Self-hosting (#82).</strong> After the lexer (S.1) come the parser, formatter, <code>eye doc</code> and the checker in Eyelang. Then the compiler builds itself, and CI checks that the second build matches the first. Releases will publish the compiler&#39;s generated C as a bootstrap seed, so building Eyelang never needs an existing Eyelang binary.</li><li><strong>Compile speed (open question 47).</strong> The owner&#39;s targets: a program of a million lines built in a minute, then in 10 seconds, then in 1 second. Today a million lines check in 3.8 s, but an optimised build of 100,000 lines takes 4 minutes. The first step is C in one unit per module, compiled in parallel and cached by hash.</li><li><strong>Packages (P0, waiting on the owner).</strong> <code>[dependencies]</code> in <code>eye.toml</code> from paths and git, an <code>eye.lock</code> with content hashes, a cache and <code>eye vendor</code>. Contracts shared between programs come with it (open question 18).</li><li><strong>Several runners on one database</strong> (open question 28). With it, pipelines over entity sets compiled to SQL, which load every entity into memory today.</li><li><strong>Runs pinned to the code they started on</strong> (open question 41). The runner would keep each version of a program while runs paused in it remain, and start new runs on the newest.</li><li><strong>Time-travel debugging</strong> (open question 32). Checkpoints and recorded steps already make every moment of a run reachable again. <code>eye test --debug</code> on a failing test comes first, then <code>eye debug RUN</code> and a Debug Adapter Protocol server with step back.</li></ul><h3 id="v1-0" tabindex="-1">v1.0 <a class="header-anchor" href="#v1-0" aria-label="Permalink to &quot;v1.0&quot;">​</a></h3><ul><li>A syntax freeze, after which old code keeps working.</li><li>Migration tooling: <code>eye fix</code> rewrites for every change before the freeze.</li><li><code>eye why</code>, to explain the compiler&#39;s decisions.</li><li>Hot code replacement for running programs.</li><li>Complete documentation.</li></ul><p>Before v1.0 the language still changes whenever real programs show a better way. Each change comes with a rewrite for existing code, not a compatibility rule. Attribute macros are considered only after v1.0, if real code keeps repeating the same patterns (open question 7).</p><h3 id="questions-still-open" tabindex="-1">Questions still open <a class="header-anchor" href="#questions-still-open" aria-label="Permalink to &quot;Questions still open&quot;">​</a></h3><p><a href="/design/open-questions">Open questions</a> has each in full. The ones not yet decided:</p><ul><li><strong>Views and data:</strong> time conditions in views such as &quot;idle for 20 minutes&quot; (1); exposing entities and jobs to other services (3).</li><li><strong>Jobs and runs:</strong> a <code>migrate</code> for a job&#39;s resume points (4); several runners on one database (28); runs pinned to their code (41); what <code>main</code> repeats on each start (40); one shape for &quot;time ran out&quot; across <code>poll!</code>, <code>next!</code> and <code>approval!</code> (37).</li><li><strong>Packages and contracts:</strong> packages (5); contracts shared by programs (18); a module with two contracts (39); who may publish an event (35); the two meanings of <code>@destructive</code> (36); a permission model for effects at run time (46).</li><li><strong>Models:</strong> streaming model output (10); prompts in template files (11); prices and routing (30).</li><li><strong>Syntax and types:</strong><ul><li>request-scoped values (12);</li><li>one canonical <code>if</code> (13);</li><li><code>if let</code> (14);</li><li>a choice&#39;s label (15);</li><li>where <code>!</code> goes on a helper (23);</li><li><code>Self</code> in traits (24);</li><li>literals in a <code>dyn</code> context (25);</li><li><code>Option</code> parameters with defaults (31);</li><li>the effects of a stored function (33);</li><li>slices that keep large values alive (38);</li><li>regex patterns checked when compiled (44).</li></ul></li><li><strong>Runtime and tools:</strong> what <code>@memory</code> measures natively (26); one flag for the store (27); task groups&#39; shape (29); time-travel debugging (32); unused recordings in fakes (16); compile speed (47); attribute macros after v1.0 (7).</li></ul><h2 id="how-this-page-stays-true" tabindex="-1">How this page stays true <a class="header-anchor" href="#how-this-page-stays-true" aria-label="Permalink to &quot;How this page stays true&quot;">​</a></h2><p>The plan is decided by real programs: the lab&#39;s workloads are the test of every new rule. <a href="https://github.com/ruxxzebre/eyelang/blob/dev/ROADMAP.md" target="_blank" rel="noreferrer">ROADMAP.md</a> holds the order, and <code>task next</code> prints what is next from the repository&#39;s current state. When a version is released or a task here lands, this page is updated with it.</p>',48)])])}const p=t(n,[["render",r]]);export{g as __pageData,p as default};
